const spriteAssets={"cow": "assets/animals/farm/cow.webp", "duck": "assets/animals/farm/duck.webp", "hen": "assets/animals/farm/hen.webp", "horse": "assets/animals/farm/horse.webp", "pig": "assets/animals/farm/pig.webp", "sheep": "assets/animals/farm/sheep.webp", "cat": "assets/animals/pets/cat.webp", "dog": "assets/animals/pets/dog.webp", "hamster": "assets/animals/pets/hamster.webp", "parrot": "assets/animals/pets/parrot.webp", "rabbit": "assets/animals/pets/rabbit.webp", "turtle": "assets/animals/pets/turtle.webp", "clownfish": "assets/animals/sea/clownfish.webp", "dolphin": "assets/animals/sea/dolphin.webp", "octopus": "assets/animals/sea/octopus.webp", "sea_turtle": "assets/animals/sea/sea_turtle.webp", "shark": "assets/animals/sea/shark.webp", "whale": "assets/animals/sea/whale.webp", "elephant": "assets/animals/wild/elephant.webp", "giraffe": "assets/animals/wild/giraffe.webp", "lion": "assets/animals/wild/lion.webp", "monkey": "assets/animals/wild/monkey.webp", "tiger": "assets/animals/wild/tiger.webp", "zebra": "assets/animals/wild/zebra.webp", "fish": "assets/animals/sea/clownfish.webp", "star_coin": "assets/game/props/star_coin.webp", "heart": "assets/game/props/heart.webp", "crystal_coin": "assets/game/props/crystal_coin.webp", "golden_key": "assets/game/props/golden_key.webp", "portal_token": "assets/game/props/portal_token.webp"};
Object.assign(spriteAssets,{"bear": "assets/game/animals/bear.webp", "crab": "assets/game/animals/crab.webp", "flamingo": "assets/game/animals/flamingo.webp", "frog": "assets/game/animals/frog.webp", "blue_robot_1": "assets/game/counting/blue_robot_1.webp", "blue_robot_2": "assets/game/counting/blue_robot_2.webp", "blue_robot_3": "assets/game/counting/blue_robot_3.webp", "blue_robot_4": "assets/game/counting/blue_robot_4.webp", "blue_robot_5": "assets/game/counting/blue_robot_5.webp", "orange_robot_1": "assets/game/counting/orange_robot_1.webp", "orange_robot_2": "assets/game/counting/orange_robot_2.webp", "orange_robot_3": "assets/game/counting/orange_robot_3.webp", "orange_robot_4": "assets/game/counting/orange_robot_4.webp", "orange_robot_5": "assets/game/counting/orange_robot_5.webp", "farm": "assets/game/locations/farm.webp", "house": "assets/game/locations/house.webp", "palm": "assets/game/locations/palm.webp", "sea": "assets/game/locations/sea.webp", "apple": "assets/game/props/apple.webp", "carrot": "assets/game/props/carrot.webp", "sun": "assets/game/props/sun.webp", "water": "assets/game/props/water.webp", "wave": "assets/game/props/water.webp", "jungle": "assets/game/locations/palm.webp"});
const wrap=(body,cls='')=>`<svg class="art ${cls}" viewBox="0 0 160 140" aria-hidden="true"><defs><linearGradient id="shine" x2="0" y2="1"><stop stop-color="#fff" stop-opacity=".45"/><stop offset="1" stop-color="#fff" stop-opacity="0"/></linearGradient></defs><ellipse cx="80" cy="128" rx="48" ry="7" fill="#18113d" opacity=".15"/>${body}</svg>`;
const eyes=(x=58,y=57,gap=42)=>`<ellipse cx="${x}" cy="${y}" rx="9" ry="12" fill="white"/><ellipse cx="${x+gap}" cy="${y}" rx="9" ry="12" fill="white"/><ellipse cx="${x+2}" cy="${y+1}" rx="5" ry="7" fill="#242040"/><ellipse cx="${x+gap-2}" cy="${y+1}" rx="5" ry="7" fill="#242040"/><circle cx="${x+3}" cy="${y-2}" r="2" fill="white"/><circle cx="${x+gap-1}" cy="${y-2}" r="2" fill="white"/>`;
const smile=`<path d="M68 83 Q80 96 93 82" fill="none" stroke="#343047" stroke-width="4" stroke-linecap="round"/>`;
const head=(color,ears='',details='')=>wrap(`${ears}<ellipse cx="80" cy="79" rx="49" ry="44" fill="${color}" stroke="#392750" stroke-width="3"/><ellipse cx="70" cy="54" rx="32" ry="17" fill="url(#shine)"/>${eyes(59,68,42)}${details}${smile}`);
export function art(name,cls=''){
 if(spriteAssets[name])return `<img class="art ${cls} sprite" src="${spriteAssets[name]}" alt="" aria-hidden="true" draggable="false">`;
 let s='';
 switch(name){
 case 'star': s=wrap('<path d="M80 7 99 46 144 53 112 85 119 130 80 109 40 130 48 85 16 53 61 46Z" fill="#ffdd54" stroke="#e39728" stroke-width="5"/><path d="M80 21 91 50 70 64 45 58 66 54Z" fill="#fff2ae"/>');break;
 case 'heart':s=wrap('<path d="M80 119C-25 49 41-18 80 33 119-18 185 49 80 119" fill="#ff526d" stroke="#a72c64" stroke-width="4"/>');break;
 case 'diamond':s=wrap('<path d="M80 8 133 65 80 126 27 65Z" fill="#44cfff" stroke="#4375ca" stroke-width="4"/><path d="M80 8 80 126 27 65Z" fill="#8aeeff"/><path d="M27 65H133" stroke="#4375ca" stroke-width="3"/>');break;
 case 'sun':s=wrap(`<g stroke="#ffcc43" stroke-width="9">${Array.from({length:8},(_,i)=>`<path d="M80 8V23" transform="rotate(${i*45} 80 70)"/>`).join('')}</g><circle cx="80" cy="70" r="36" fill="#ffdd54"/>${eyes(67,64,26)}<path d="M69 86Q80 96 91 85" fill="none" stroke="#b97523" stroke-width="3"/>`);break;
 case 'apple':s=wrap('<path d="M80 37Q29 12 24 69T80 122Q139 139 139 70T80 37" fill="#fc5475" stroke="#a82a50" stroke-width="4"/><path d="M80 39Q73 14 88 9" fill="none" stroke="#80503d" stroke-width="7"/><path d="M87 28Q114-1 132 19Q118 40 87 28" fill="#83ce67"/><ellipse cx="49" cy="59" rx="11" ry="20" fill="#ffb1b7" transform="rotate(25 49 59)"/>');break;
 case 'wave':s=wrap('<path d="M12 100Q38 33 86 34Q132 33 137 71Q106 41 93 72Q82 95 133 101L147 121H10Z" fill="#46b9fa" stroke="#2a77bd" stroke-width="4"/><path d="M19 113Q48 89 81 108T146 111" fill="none" stroke="#a8efff" stroke-width="8"/>');break;
 case 'banana':s=wrap('<path d="M32 15Q42 104 136 77Q115 137 60 118T32 15" fill="#ffdf4d" stroke="#d79c38" stroke-width="4"/><path d="M43 55Q56 109 112 96" fill="none" stroke="#fff6ac" stroke-width="7"/>');break;
 case 'carrot':s=wrap('<path d="M56 43Q96 24 114 53L42 125Z" fill="#ff9946" stroke="#c4662d" stroke-width="4"/><path d="M83 37 75 6M91 39 114 10M97 44 137 32" stroke="#64be62" stroke-width="13" stroke-linecap="round"/><path d="M58 74 75 80M73 59 90 65" stroke="#db7332" stroke-width="4"/>');break;
 case 'butterfly':s=wrap('<path d="M78 67Q-1-17 17 69Q-2 124 73 98M82 67Q161-17 143 69Q162 124 87 98" fill="#bf8bfa" stroke="#8153c0" stroke-width="4"/><path d="M80 45V113M78 47 63 23M82 47 97 23" stroke="#55406b" stroke-width="6" stroke-linecap="round"/><ellipse cx="44" cy="55" rx="15" ry="23" fill="#edbeff"/><ellipse cx="116" cy="55" rx="15" ry="23" fill="#edbeff"/>');break;
 case 'frog':s=wrap(`<ellipse cx="80" cy="99" rx="52" ry="27" fill="#6fcf72"/><ellipse cx="37" cy="117" rx="26" ry="10" fill="#52ae62"/><ellipse cx="123" cy="117" rx="26" ry="10" fill="#52ae62"/><ellipse cx="80" cy="69" rx="58" ry="39" fill="#83df75"/><circle cx="52" cy="38" r="22" fill="#83df75"/><circle cx="108" cy="38" r="22" fill="#83df75"/>${eyes(52,38,56)}${smile}<circle cx="41" cy="76" r="8" fill="#f6a9b7"/><circle cx="119" cy="76" r="8" fill="#f6a9b7"/>`);break;
 case 'elephant':s=head('#a5b5ce','<ellipse cx="32" cy="72" rx="28" ry="37" fill="#9baac4"/><ellipse cx="128" cy="72" rx="28" ry="37" fill="#9baac4"/>','<path d="M81 83V116Q81 140 106 118" stroke="#889bb9" stroke-width="22" fill="none" stroke-linecap="round"/>');break;
 case 'tiger':s=head('#ffb252','<circle cx="42" cy="37" r="19" fill="#e89848"/><circle cx="118" cy="37" r="19" fill="#e89848"/>','<path d="M66 36 71 51M91 36 86 51M34 72 49 77M126 72 111 77M39 94 53 94M121 94 107 94" stroke="#573a3d" stroke-width="8"/><ellipse cx="80" cy="86" rx="23" ry="14" fill="#fff0cf"/><path d="m73 80 14 0-7 10Z" fill="#694651"/>');break;
 case 'cat':s=head('#e8b082','<path d="M33 60 35 12 68 41M92 41 125 12 128 60" fill="#e8b082" stroke="#71525c" stroke-width="3"/>','<path d="m73 83 14 0-7 8Z" fill="#da7d93"/><path d="M33 88 6 80M33 95 6 98M127 88 154 80M127 95 154 98" stroke="#71525c" stroke-width="3"/>');break;
 case 'dog':s=head('#daaa77','<ellipse cx="32" cy="66" rx="19" ry="39" fill="#936349" transform="rotate(18 32 66)"/><ellipse cx="128" cy="66" rx="19" ry="39" fill="#936349" transform="rotate(-18 128 66)"/>','<ellipse cx="80" cy="88" rx="23" ry="19" fill="#f6d4a5"/><ellipse cx="80" cy="80" rx="12" ry="8" fill="#494051"/><path d="M76 99Q80 122 88 98" fill="#f493a9"/>');break;
 case 'cow':s=head('#fff4dc','<path d="M40 43 25 14 51 29M109 29 135 14 120 43" fill="#d1bb80"/><ellipse cx="22" cy="56" rx="19" ry="12" fill="#d9b89f"/><ellipse cx="138" cy="56" rx="19" ry="12" fill="#d9b89f"/>','<path d="M38 54Q36 30 64 38L66 57Z" fill="#5b5262"/><ellipse cx="80" cy="94" rx="33" ry="19" fill="#f6b2b7"/><circle cx="66" cy="93" r="4" fill="#b16e89"/><circle cx="94" cy="93" r="4" fill="#b16e89"/>');break;
 case 'monkey':s=head('#c48d61','<circle cx="28" cy="65" r="24" fill="#b78055"/><circle cx="132" cy="65" r="24" fill="#b78055"/>','<path d="M40 79Q34 36 63 51Q80 27 98 51Q128 36 120 81Q119 113 80 117Q41 113 40 79" fill="#f6d5a9"/> '+eyes(61,68,38));break;
 case 'bear':s=head('#b78964','<circle cx="40" cy="37" r="22" fill="#9b7056"/><circle cx="120" cy="37" r="22" fill="#9b7056"/>','<ellipse cx="80" cy="89" rx="26" ry="20" fill="#dfbd97"/><ellipse cx="80" cy="80" rx="12" ry="8" fill="#4d3f4a"/>');break;
 case 'hamster':s=head('#efca99','<circle cx="43" cy="35" r="18" fill="#e9b682"/><circle cx="117" cy="35" r="18" fill="#e9b682"/>','<ellipse cx="80" cy="96" rx="35" ry="22" fill="#fff3d7"/><circle cx="80" cy="83" r="6" fill="#ed9ea3"/>');break;
 case 'lion':s=wrap(`<circle cx="80" cy="72" r="60" fill="#b8794d"/><circle cx="80" cy="76" r="44" fill="#f5c56c"/>${eyes(61,68,38)}<ellipse cx="80" cy="88" rx="20" ry="15" fill="#ffe5ac"/>${smile}`);break;
 case 'sheep':s=wrap(`${Array.from({length:10},(_,i)=>`<circle cx="${80+45*Math.cos(i*.628)}" cy="${72+42*Math.sin(i*.628)}" r="23" fill="#fff8e9" stroke="#d7cce2" stroke-width="2"/>`).join('')}<ellipse cx="80" cy="78" rx="35" ry="39" fill="#8e7c9e"/>${eyes(65,68,30)}${smile}`);break;
 case 'giraffe':s=wrap('<path d="M56 124 68 55 96 55 107 124" fill="#f3c363" stroke="#b48a43" stroke-width="3"/><path d="M66 29 63 10M96 29 100 10" stroke="#9c7951" stroke-width="8"/><ellipse cx="82" cy="48" rx="33" ry="27" fill="#f7cf77"/><ellipse cx="52" cy="31" rx="15" ry="8" fill="#e8ac52"/><ellipse cx="115" cy="31" rx="15" ry="8" fill="#e8ac52"/>'+eyes(69,43,25)+'<path d="M72 75 86 86 70 95M94 98 85 108 99 116" stroke="#b98349" stroke-width="9"/>');break;
 case 'zebra':case 'horse':s=head(name==='zebra'?'#fbf8ee':'#bb8b67','<path d="M47 45 41 8 65 33M94 33 119 8 115 45" fill="'+(name==='zebra'?'#ddd9df':'#bb8b67')+'" stroke="#63516a" stroke-width="3"/>',`${name==='zebra'?'<path d="M67 35 73 55M91 35 86 55M35 72 48 80M125 72 112 80M40 94 53 97M120 94 107 97" stroke="#55445e" stroke-width="8"/>':''}<ellipse cx="80" cy="96" rx="28" ry="18" fill="#b4a6b5"/>`);break;
 case 'flamingo':case 'parrot':case 'hen':s=wrap(`<path d="M72 107 65 128M91 107 99 128" stroke="#ce8b46" stroke-width="5"/><ellipse cx="80" cy="85" rx="40" ry="34" fill="${name==='parrot'?'#68c977':name==='hen'?'#fff5df':'#f59bc6'}"/><path d="M67 84Q29 112 45 63" fill="${name==='parrot'?'#56a7f2':'#e883b7'}"/><path d="M91 68Q117 65 107 41" fill="none" stroke="${name==='parrot'?'#68c977':name==='hen'?'#fff5df':'#f59bc6'}" stroke-width="23"/><circle cx="109" cy="36" r="22" fill="${name==='parrot'?'#f77778':name==='hen'?'#fff5df':'#f59bc6'}"/><path d="M126 33 149 46 126 49" fill="#f4c959"/><circle cx="113" cy="31" r="6" fill="white"/><circle cx="115" cy="31" r="3" fill="#33324b"/>${name==='hen'?'<path d="M98 17Q92-1 106 11Q119-9 120 16" fill="#f17682"/>':''}`);break;
 case 'fish':case 'whale':case 'dolphin':case 'shark':s=wrap(`<path d="M36 79 8 51 13 105Z" fill="#569fe0"/><ellipse cx="85" cy="80" rx="57" ry="35" fill="${name==='shark'?'#8ba9c9':name==='fish'?'#ffc469':'#6cbeef'}"/><path d="M70 48 82 16 100 48" fill="#559cd8"/><path d="M77 103 91 121 104 97" fill="#559cd8"/><ellipse cx="97" cy="93" rx="38" ry="16" fill="#c7edfa"/><circle cx="113" cy="71" r="10" fill="white"/><circle cx="115" cy="72" r="5" fill="#293755"/><path d="M121 93Q131 98 139 89" stroke="#487caa" stroke-width="3" fill="none"/>${name==='dolphin'?'<path d="M131 76 156 86 130 93" fill="#6cbeef"/>':''}`);break;
 case 'octopus':s=wrap(`<g stroke="#b58df0" stroke-width="15" fill="none" stroke-linecap="round">${[26,48,70,92,114,136].map((x,i)=>`<path d="M80 83Q${x} 146 ${x-10} ${105+i%2*14}"/>`).join('')}</g><ellipse cx="80" cy="61" rx="44" ry="45" fill="#c9a2f7"/>${eyes(62,59,36)}${smile}`);break;
 case 'crab':s=wrap('<g stroke="#f5757e" fill="none" stroke-width="8"><path d="M47 82 19 62 13 38M113 82 141 62 147 38M48 96 16 108M112 96 144 108"/></g><ellipse cx="80" cy="89" rx="43" ry="29" fill="#ff848c"/><circle cx="47" cy="62" r="14" fill="#ff848c"/><circle cx="113" cy="62" r="14" fill="#ff848c"/>'+eyes(47,59,66));break;
 case 'robot':s=wrap('<path d="M53 42V21H107V42" stroke="#6e91bb" stroke-width="7" fill="none"/><rect x="30" y="35" width="100" height="64" rx="24" fill="#73d5fa" stroke="#4d6fa5" stroke-width="4"/><rect x="42" y="47" width="76" height="38" rx="14" fill="#28365a"/><circle cx="62" cy="65" r="8" fill="#91f7ff"/><circle cx="98" cy="65" r="8" fill="#91f7ff"/><rect x="51" y="99" width="58" height="24" rx="8" fill="#9ee9fc"/>');break;
 case 'farm':case 'house':s=wrap(`<path d="M21 63 80 12 139 63Z" fill="${name==='farm'?'#f37b83':'#b593f1'}" stroke="#675180" stroke-width="4"/><rect x="35" y="62" width="90" height="62" rx="4" fill="${name==='farm'?'#ffd39a':'#a6dcef'}"/><rect x="66" y="82" width="28" height="42" rx="6" fill="#8067a5"/><rect x="43" y="76" width="16" height="18" rx="3" fill="#fff5b0"/><rect x="101" y="76" width="16" height="18" rx="3" fill="#fff5b0"/>`);break;
 case 'sea':return art('wave',cls);
 case 'jungle':s=wrap('<path d="M68 127 76 36 88 36 94 127" fill="#a88259"/><path d="M82 40Q19-19 8 65Q39 36 82 40M82 40Q144-19 153 65Q120 36 82 40M82 40Q69-13 37 7Q59 16 82 40M82 40Q97-13 130 7Q106 16 82 40" fill="#71ca83" stroke="#48a86b" stroke-width="3"/>');break;
 default: s=wrap(`<text x="80" y="90" text-anchor="middle" font-size="44" font-family="sans-serif" fill="#392956">${name}</text>`);
 }
 return s.replace('class="art "',`class="art ${cls}"`);
}
export const crystal=(i,small=false)=>`<span class="crystal ${small?'small':''}" style="--i:${i}" role="img" aria-label="${['Rainbow','Number','Animal'][i]} crystal"></span>`;
export function robotScene(right=false){return `<svg viewBox="0 0 320 300" aria-hidden="true"><ellipse cx="160" cy="276" rx="100" ry="12" fill="#18113933"/><path d="M160 60V30" stroke="#9aafd5" stroke-width="10"/><circle cx="160" cy="25" r="15" fill="${right?'#57aafa':'#fc637d'}"/><rect x="70" y="60" width="180" height="122" rx="40" fill="#a2d9f6" stroke="#6679b3" stroke-width="5"/><rect x="88" y="80" width="142" height="70" rx="27" fill="#263859"/><ellipse cx="124" cy="110" rx="13" ry="18" fill="#6eeeff"/><ellipse cx="194" cy="110" rx="13" ry="18" fill="#6eeeff"/><path d="M139 136Q160 151 181 136" stroke="#6eeeff" stroke-width="5" fill="none"/><rect x="101" y="180" width="118" height="69" rx="18" fill="#92bcec"/><rect x="164" y="192" width="42" height="41" rx="8" fill="${right?'#ffa462':'#a97df0'}"/><rect x="92" y="245" width="62" height="27" rx="10" fill="${right?'#ffe365':'#79d890'}"/><rect x="169" y="245" width="62" height="27" rx="10" fill="#82a8da"/></svg>`;}
